// One shape for all three entry points. Only the console webhook carries a
// trigger_id; the secret header is checked by the webhook node itself and is
// deliberately not copied forward.
const j = $json || {};
const body = j.body && typeof j.body === 'object' ? j.body : null;
const tid = body && typeof body.trigger_id === 'string' && /^trg-[0-9a-f]{6,32}$/.test(body.trigger_id) ? body.trigger_id : null;
return { json: {
  trigger_id: tid,
  source: body ? 'console' : (j.timestamp ? 'schedule' : 'manual'),
  started_at: new Date().toISOString(),
} };

// Parse the first markdown table that has Technique and Status columns.
const md = String($('Fetch attack matrix').first().json.data || '');
let headers = null; const rows = [];
for (const raw of md.split('\n')) {
  const line = raw.trim();
  if (!line.startsWith('|') || !line.endsWith('|')) { if (headers && rows.length) break; continue; }
  const cells = line.slice(1, -1).split('|').map(c => c.trim());
  if (cells.every(c => /^:?-{2,}:?$/.test(c))) continue;
  if (!headers) { if (cells.some(c => /technique/i.test(c)) && cells.some(c => /status/i.test(c))) headers = cells; continue; }
  if (cells[0].toLowerCase() === headers[0].toLowerCase()) continue;
  rows.push(Object.fromEntries(headers.map((h, i) => [h, (cells[i] || '').replace(/`/g, '')])));
}
if (!rows.length) throw new Error('attack matrix: no table with Technique and Status columns');
const tKey = headers.find(h => /technique/i.test(h)), sKey = headers.find(h => /status/i.test(h));
const coverage_matrix = rows.map(r => ({ ...r, state: /validated/i.test(r[sKey]) ? 'VALIDATED' : (r[sKey] || '').split(' ')[0].toUpperCase() }));
const existing_rules = $('Fetch existing Sigma list').all().map(i => i.json.name).filter(n => /\.ya?ml$/i.test(n || ''));
// Techniques that already have an open ai-proposal PR (not merged yet, so not in the matrix): never re-propose them.
const open_proposals = [];
try { for (const i of $('Fetch open proposals').all()) {
  const ref = String(((i.json || {}).head || {}).ref || '');
  const m = ref.match(/^ai-proposal\/t(\d{4})(?:-(\d{3}))?-\d{8}-/);
  if (m) open_proposals.push('T' + m[1] + (m[2] ? '.' + m[2] : ''));
} } catch (_) {}
const covered = coverage_matrix.map(r => (String(r[tKey]).match(/T\d{4}(?:\.\d{3})?/) || [''])[0]).filter(Boolean);
const context = {
  coverage_matrix, existing_rules,
  techniques_already_covered: [...new Set([...covered, ...open_proposals])], open_proposals,
  environment: 'Windows 10 victim with Sysmon + Wazuh 4.14; Ubuntu victim auditd broken (never propose Linux rules); no AD domain; no cloud sources',
};
const CANDIDATES = {"T1021.001": "Remote Services: Remote Desktop Protocol", "T1021.002": "Remote Services: SMB/Windows Admin Shares", "T1021.003": "Remote Services: Distributed Component Object Model", "T1021.005": "Remote Services: VNC", "T1021.006": "Remote Services: Windows Remote Management", "T1053.002": "Scheduled Task/Job: At", "T1053.005": "Scheduled Task/Job: Scheduled Task", "T1098.002": "Account Manipulation: Additional Email Delegate Permissions", "T1098.005": "Account Manipulation: Device Registration", "T1098.007": "Account Manipulation: Additional Local or Domain Groups", "T1547.001": "Boot or Logon Autostart Execution: Registry Run Keys / Startup Folder", "T1547.002": "Boot or Logon Autostart Execution: Authentication Package", "T1547.003": "Boot or Logon Autostart Execution: Time Providers", "T1547.004": "Boot or Logon Autostart Execution: Winlogon Helper DLL", "T1547.005": "Boot or Logon Autostart Execution: Security Support Provider", "T1547.008": "Boot or Logon Autostart Execution: LSASS Driver", "T1547.009": "Boot or Logon Autostart Execution: Shortcut Modification", "T1547.010": "Boot or Logon Autostart Execution: Port Monitors", "T1547.012": "Boot or Logon Autostart Execution: Print Processors", "T1547.014": "Boot or Logon Autostart Execution: Active Setup", "T1553.002": "Subvert Trust Controls: Code Signing", "T1553.003": "Subvert Trust Controls: SIP and Trust Provider Hijacking", "T1553.004": "Subvert Trust Controls: Install Root Certificate", "T1553.005": "Subvert Trust Controls: Mark-of-the-Web Bypass", "T1553.006": "Subvert Trust Controls: Code Signing Policy Modification", "T1555.003": "Credentials from Password Stores: Credentials from Web Browsers", "T1555.004": "Credentials from Password Stores: Windows Credential Manager", "T1555.005": "Credentials from Password Stores: Password Managers", "T1685.001": "Disable or Modify Tools: Disable or Modify Windows Event Log", "T1685.003": "Disable or Modify Tools: Modify or Spoof Tool UI", "T1685.005": "Disable or Modify Tools: Clear Windows Event Logs", "T1686.003": "Disable or Modify System Firewall: Windows Host Firewall"};
const candidates = Object.entries(CANDIDATES).filter(([t]) => !context.techniques_already_covered.includes(t));
// Short per-family references: the right event type and fields, and the
// mistakes earlier drafts made. Injected next to the candidate list.
const FAMILY_REF = [
  'PERSISTENCE (T1547, T1053): Run-key persistence = registry VALUE writes under existing Run keys = Sysmon EID 13 SetValue (category registry_set); TargetObject = the Run key path; Image = the writing process (reg.exe, powershell.exe — NEVER filter these); Details = the value data being written. EID 12 (registry_add/delete) is key create/delete only, the wrong event for value writes. Scheduled tasks: process_creation of schtasks.exe with /create in CommandLine.',
  'CREDENTIAL ACCESS (T1555, T1003): Sysmon does not log file reads. Use process_creation (EID 1) when the theft is visible in the command line (Image, CommandLine naming Login Data, logins.json, key4.db, vaultcmd), or process_access (EID 10) for memory reads: SourceImage, TargetImage, GrantedAccess. process_access has no Image or CommandLine; image_load has no TargetImage.',
  'EXECUTION (T1059 and LOLBins): process_creation (EID 1): match the binary with Image|endswith or OriginalFileName, arguments with CommandLine|contains, suspicious launchers with ParentImage.',
  'ALL FAMILIES: filters exclude known-benign actors only, never the primary attacker tool for the technique.',
].join('\n');
const system = "You are the Detection Engineering AI. Analyze coverage, pick ONE highest-value gap (priority: Windows persistence T1547/T1053 variants, defense impairment T1685/T1686/T1553 (T1562 was revoked in ATT&CK v19 and replaced by T1685/T1686), credential access T1555/T1098 variants, lateral-movement prep T1021; never Linux/cloud/AD/duplicates of existing). Technique IDs must be current ATT&CK Enterprise IDs that apply to Windows; deprecated, revoked or Linux-only (sub-)techniques are rejected, and technique_name must be the official ATT&CK name for that ID. Write ONE Sigma v2.1 single-document rule (no correlations), logsource category process_creation/registry_*/image_load/file_event, Sysmon field names (Image, CommandLine, TargetFilename, TargetObject), tight patterns, realistic falsepositives, level high/medium. The rule must contain title, id (a UUID), status: experimental, description, logsource, detection with named items and a condition that references only those names (never start an item name with not, and, or), falsepositives, level and tags (attack.<tactic> and attack.<technique id in lowercase>). Detection logic rules: (1) conditions must be satisfiable by a SINGLE event; never require two mutually exclusive field values with AND. (2) only use fields that exist on the declared event type; for Sysmon registry events (EID 12/13/14) use only EventID, TargetObject, Details, Image, ProcessGuid, ProcessId, User (no ParentImage, no CommandLine, no hashes). Output strict JSON only: {gap_analysis, technique (TXXXX.XXX), technique_name, title, reasoning, sigma_yaml}.\n\nExample of a minimal valid sigma_yaml (format only; this technique is already covered, do not reuse it):\ntitle: PowerShell Encoded Command From Office Application\nid: 3b6f2c1e-8a4d-4c2b-9e1f-7a5d0c3b2e41\nstatus: experimental\ndescription: Detects PowerShell started by an Office application with an encoded command line.\nlogsource:\n  product: windows\n  category: process_creation\ndetection:\n  selection_parent:\n    ParentImage|endswith:\n      - '\\WINWORD.EXE'\n      - '\\EXCEL.EXE'\n  selection_child:\n    Image|endswith: '\\powershell.exe'\n    CommandLine|contains:\n      - ' -enc '\n      - ' -EncodedCommand '\n  filter_admin:\n    User|contains: 'svc_deploy'\n  condition: selection_parent and selection_child and not filter_admin\nfalsepositives:\n  - Office add-ins that launch signed PowerShell helpers\nlevel: high\ntags:\n  - attack.execution\n  - attack.t1059.001\n";
return [{ json: { context, covered: context.techniques_already_covered, llm_body: {
  model: 'qwen/qwen3.8-27b', max_tokens: 2500,
  messages: [{ role: 'system', content: system }, { role: 'user', content:
    'Technique-family reference (follow it):\n' + FAMILY_REF + '\n\n'
    + 'Choose your technique from this list of current, Windows-applicable ATT&CK IDs that are not yet covered (use the exact ID and name):\n'
    + candidates.map(([t, n]) => t + ' ' + n).join('\n')
    + '\n\nAlready covered, never choose: ' + context.techniques_already_covered.join(', ') + '. Answer with the JSON object only.\n\n' + JSON.stringify(context) }],
} } }];

// No PR unless the same checks as the repo CI pass (sigma check + splunk convert).
const draft = $('Validate fields').first().json, r = $json.body || {};
if ($json.statusCode === 200 && r.ok === true) return { json: { ...draft, ok: true } };
const errs = Array.isArray(r.errors) && r.errors.length ? r.errors : ['validator HTTP ' + $json.statusCode];
return { json: { ok: false, step: 'sigma', detail: 'sigma pre-check: ' + errs.join('; ').slice(0, 400), llm_content: draft.llm_content } };

// One retry with the rejection fed back to the model.
const err = $json.detail || 'validation failed';
const prev = String($json.llm_content || ((($('LLM draft').first().json.choices || [])[0] || {}).message || {}).content || '').slice(-6000);
const base = $('Assemble context').first().json.llm_body;
const messages = [...base.messages, { role: 'assistant', content: prev },
  { role: 'user', content: 'Your answer was rejected: ' + err + '\nFix exactly that problem and answer with the complete corrected JSON object only.' }];
return { json: { llm_body: { ...base, messages }, first_error: err } };

// No PR unless the same checks as the repo CI pass (sigma check + splunk convert).
const draft = $('Validate fields (retry)').first().json, r = $json.body || {};
if ($json.statusCode === 200 && r.ok === true) return { json: { ...draft, ok: true } };
const errs = Array.isArray(r.errors) && r.errors.length ? r.errors : ['validator HTTP ' + $json.statusCode];
return { json: { ok: false, step: 'sigma', detail: 'sigma pre-check: ' + errs.join('; ').slice(0, 400), llm_content: draft.llm_content } };

// The draft that passed every check, from the first attempt or the retry.
let retried = false; try { retried = $('Build retry request').isExecuted; } catch (_) {}
return { json: { ...$json, attempt: retried ? 2 : 1 } };

// Exactly the console contract, plus trigger_id when the run came from the console.
const v = $('Accepted draft').first().json, run = $('Run context').first().json;
const body = { technique: v.technique, title: v.title, sigma_yaml: v.sigma_yaml, reasoning: v.reasoning,
  pr_url: $json.html_url, pr_number: parseInt($json.number, 10), branch: v.branch };
if (run.trigger_id) body.trigger_id = run.trigger_id;
return { json: { proposal: body, attempt: 1 } };

// 201 -> done; 429 -> rate_limited, stop (no retry); 422 -> repair what the
// message names and retry once; anything else -> failed.
const code = $json.statusCode, body = $json.body || {};
const msg = typeof body === 'object' ? String(body.detail || JSON.stringify(body)) : String(body);
const prev = $('Build proposal').first().json;
if (code === 201) return { json: { outcome: 'registered', proposal_id: body.id, pr_number: prev.proposal.pr_number } };
// 429 = the console already holds this technique from the last 10 minutes: this PR is a duplicate.
if (code === 429) return { json: { outcome: 'rate_limited', detail: 'rate_limited: ' + msg.slice(0, 200) } };
if (code === 422) return { json: { outcome: 'repair', detail: '422: ' + msg.slice(0, 250), message_422: msg } };
return { json: { outcome: 'failed', detail: 'console HTTP ' + code + ': ' + msg.slice(0, 160) + ' (PR #' + prev.proposal.pr_number + ' is open but not registered)' } };

// One deterministic repair pass, driven by the field names in the 422 text.
console.log('console 422: ' + $json.message_422);
const p = { ...$('Build proposal').first().json.proposal }, v = $('Accepted draft').first().json, m = $json.message_422;
if (/pr_number/.test(m)) p.pr_number = parseInt(String(p.pr_number).replace(/\D/g, ''), 10);
if (/technique/.test(m)) p.technique = (String(p.technique).match(/T\d{4}(?:\.\d{3})?/i) || [''])[0].toUpperCase();
if (/reasoning/.test(m) && !p.reasoning) p.reasoning = v.gap_analysis;
if (/title exceeds|title/.test(m)) p.title = String(p.title || v.technique).slice(0, 300);
if (/reasoning exceeds/.test(m)) p.reasoning = String(p.reasoning).slice(0, 4000);
if (/sigma_yaml exceeds/.test(m)) p.sigma_yaml = String(p.sigma_yaml).slice(0, 20000);
if (/branch/.test(m)) p.branch = String(p.branch || v.branch).slice(0, 200);
if (/pr_url/.test(m)) p.pr_url = String(p.pr_url || '').replace(/^(?!https?:\/\/)/, 'https://');
return { json: { proposal: p, first_422: m } };

const code = $json.statusCode, body = $json.body || {};
const msg = typeof body === 'object' ? String(body.detail || JSON.stringify(body)) : String(body);
const first = $('Repair payload').first().json.first_422;
if (code === 201) return { json: { outcome: 'registered', proposal_id: body.id, pr_number: $('Repair payload').first().json.proposal.pr_number, note: 'registered after repairing 422: ' + first } };
if (code === 429) return { json: { outcome: 'failed', detail: 'rate_limited: ' + msg.slice(0, 160) + ' (PR is open but not registered)' } };
return { json: { outcome: 'failed', detail: 'console 422 after retry: ' + msg.slice(0, 200) } };

const r = $json, v = $('Accepted draft').first().json;
const pr = $('Open PR').first().json;
return { json: { status: 'succeeded', proposal_id: r.proposal_id,
  detail: `Proposed ${v.technique} ${v.title} as PR #${pr.number}`.slice(0, 300),
  telegram: `AI proposed ${v.technique}: ${v.title} — PR #${pr.number}\n${pr.html_url}\nReview: https://console.ctum.org/#/queue/${r.proposal_id}` } };

// Funnel for every failure: validation, LLM/GitHub errors and console refusals.
const j = $json || {};
let detail = j.detail;
if (!detail && j.error) detail = `${$prevNode.name}: ${String(j.error.message || j.error.description || j.error).slice(0, 200)}`;
let first = ''; try { if ($('Build retry request').isExecuted) first = $('Build retry request').first().json.first_error; } catch (_) {}
if (first && detail && detail !== first) detail = detail + ' (after 1 retry; first attempt: ' + String(first).slice(0, 120) + ')';
return { json: { status: 'failed', detail: String(detail || 'unknown failure').replace(/\s+/g, ' ').slice(0, 300) } };

// Commit or PR creation failed after the branch exists: say what failed, then the branch is removed.
const j = $json || {}, v = $('Accepted draft').first().json;
const msg = String((j.error && (j.error.message || j.error.description)) || j.error || 'unknown error').replace(/\s+/g, ' ').slice(0, 160);
return { json: { detail: `${$prevNode.name}: ${msg} (branch ${v.branch} removed)`, branch: v.branch } };
